'use strict';
// Original circular doll hat blocks; all seam lines are in cm.
(()=>{const P=DollPatterns,oldRender=P.render,oldValidate=P.validate;
const head=['head','戴帽位置頭圍',18,'連同假髮量帽口所在的一圈',3,100],ease=['hatEase','帽口鬆量',.5,'整圈增加量；無彈性布先試戴',0,5];
P.registry.beret={title:'娃娃貝雷帽',fields:[head],design:[ease,['spread','帽身外放',2,'帽頂半徑比帽口半徑多出的量',.5,12],['bandHeight','帽箍完成高',.7,'帽箍長邊對折；完成高度',.2,5]],note:'圓形帽頂＋環形帽底＋雙層帽箍。以含假髮的戴帽位置頭圍製作，適合無彈性薄布。帽底中央需挖空，內圈縫份向洞內加；先做胚帽試戴。',steps:['帽頂裁 1 片、環形帽底裁 1 片、帽箍裁 1 片。帽底中央沿內圈裁剪線挖空，不要沿縫合線剪。','帽頂與帽底正面相對，四等分記號對齊，縫合外圈後翻正。','帽箍短邊縫成環，長邊對折；四等分記號對帽底內圈，接合兩層帽箍毛邊與帽底。','試戴確認鬆緊與傾斜角度；厚布、假髮與接縫厚度可能需要增加鬆量。']};
P.registry.bucket_hat={title:'娃娃平頂漁夫帽',fields:[head],design:[ease,['crownHeight','帽身高',3,'帽頂接縫至帽簷接縫',.5,20],['brimWidth','帽簷寬',1.5,'平面環形帽簷寬；無下斜角',.5,10]],note:'圓帽頂＋直筒帽身＋雙層平面環形帽簷，是簡化平頂漁夫帽。帽簷為平面，並非下斜帽簷；帽高須配合娃娃頭形試胚調整。',steps:['帽頂裁 1 片、帽身裁 1 片，環形帽簷裁 2 片。兩片帽簷中央均沿內圈裁剪線挖空。','帽身短邊接成環，帽頂與帽身上邊四等分記號相對縫合。','兩片帽簷正面相對縫合外圈，從內圈翻正、整燙。','帽身下邊與帽簷內圈四等分記號對齊接合，內側毛邊另以包邊帶處理；包邊帶長度取帽口整圈加接頭量。']};
function dimensions(type,v){const c=v.head+v.hatEase,r=c/(2*Math.PI),R=r+(type==='beret'?v.spread:v.brimWidth);return {c,r,R};}
function validate(type,v){if(!['beret','bucket_hat'].includes(type))return oldValidate(type,v);for(const [k,l,,,min,max]of [...P.registry[type].fields,...P.registry[type].design,P.seam])if(!Number.isFinite(v[k])||v[k]<min||v[k]>max)throw Error(`${l}請輸入 ${min}–${max} cm。`);if(v.seam>=dimensions(type,v).r-.1)throw Error('縫份太寬，帽口內圈裁剪線已接近消失；請減少縫份。');}
const text=(x,y,s)=>`<text x="${x}" y="${y}" text-anchor="middle" font-size=".25" fill="#233854">${s}</text>`;
const circle=(r,hole=false)=>`<path class="seam-line" data-hole="${hole}" data-front="false" d="M ${-r} 0 A ${r} ${r} 0 1 0 ${r} 0 A ${r} ${r} 0 1 0 ${-r} 0 Z" fill="${hole?'white':'#edf2fc'}" stroke="#254fb1" stroke-width=".035"/>`;
function quarters(r){return [0,1,2,3].map(i=>{const a=i*Math.PI/2,x=r*Math.cos(a),y=r*Math.sin(a);return `<path class="match-symbol" d="M ${x-.1*Math.cos(a)} ${y-.1*Math.sin(a)} l ${.2*Math.cos(a)} ${.2*Math.sin(a)}" stroke="#0e6279" stroke-width=".03"/>`;}).join('');}
function render(type,v){if(!['beret','bucket_hat'].includes(type))return oldRender(type,v);validate(type,v);const {c,r,R}=dimensions(type,v),top=type==='beret'?R:r,m=1.8+v.seam,gap=2+2*v.seam,ringY=2*top+R+gap,stripY=ringY+R+gap,H=type==='beret'?2*v.bandHeight:v.crownHeight,w=Math.max(2*R,c)+2*m,h=stripY+H+2*m+1;
let body=`<g transform="translate(${R},${top})">${circle(top)}${quarters(top)}${text(0,0,'帽頂 · 裁 1 片')}</g><g transform="translate(${R},${ringY})">${circle(R).replace('data-front=','data-ring="true" data-front=')}${circle(r,true)}<path class="grain-symbol" d="M ${(R+r)/2} -.25 v .5 m -.08 -.12 l .08 .12 .08 -.12" fill="none" stroke="#243953" stroke-width=".025"/>${quarters(R)}${quarters(r)}${text(0,-(r+R)/2,type==='beret'?'帽底 · 裁 1 片':'帽簷 · 裁 2 片')}${text(0,0,'中央挖空')}</g><g transform="translate(0,${stripY})"><path class="seam-line" data-front="false" d="M 0 0 H ${c} V ${H} H 0 Z" fill="#edf2fc" stroke="#254fb1" stroke-width=".035"/>${text(c/2,H/2,type==='beret'?'帽箍 · 裁 1 片':'帽身 · 裁 1 片')}${[1,2,3].map(i=>`<path class="match-symbol" d="M ${c*i/4} -.1 v .2 M ${c*i/4} ${H-.1} v .2" stroke="#0e6279" stroke-width=".03"/>`).join('')}${type==='beret'?`<path d="M 0 ${H/2} H ${c}" stroke="#7b8ba2" stroke-width=".02" stroke-dasharray=".12 .1"/>`:''}</g>`;
return {svg:`<svg xmlns="http://www.w3.org/2000/svg" width="${w}cm" height="${h}cm" viewBox="0 0 ${w} ${h}" role="img" aria-label="${P.registry[type].title}"><title>${P.registry[type].title}</title><g font-family="sans-serif" transform="translate(${m},${m})">${body}</g>${text(w/2,h-.6,'短記號為四等分對合點；內圈縫份向洞內加。')}</svg>`,metrics:[['帽口完成整圈',c],['帽頂直徑',2*top],['帽底／帽簷外徑',2*R]],checks:{opening:2*Math.PI*r,strip:c,top:2*Math.PI*top,matchingTop:2*Math.PI*(type==='beret'?R:r),innerCutRadius:r-v.seam}};}
P.render=render;P.validate=validate;
})();
